/**
 * Procedural carved-stone prototypes (Step 47, round 2).
 * References: REF-004 (bosses, capitals, rib sections), REF-007 / REF-012
 * (pinnacles, crockets, finials), REF-003 (moulding profiles from arcs),
 * REF-008 (mullion sections), REF-018 / REF-020 (grotesques), REF-030.
 *
 * Every piece is built from explicit geometry — convex hulls, lathe
 * profiles made of circular arcs, extruded mouldings, foil-outline polar
 * surfaces, lofts along parametric spines and tube sweeps. No meshes are
 * imported or generated by AI. Each prototype is normalised to the unit box;
 * the stone's size vector scales it.
 */

import * as THREE from 'three'
import { ConvexGeometry } from 'three/examples/jsm/geometries/ConvexGeometry.js'
import { mergeGeometries } from 'three/examples/jsm/utils/BufferGeometryUtils.js'
import { mulberry32 } from '../skeleton/members.js'
import { foilRadiusAt, minLobeRatio } from '../skeleton/construct2d.js'
import { BOSS_LOBES, PROTO, PROTOTYPE_COUNT } from '../lithic/protos.js'

const TAU = Math.PI * 2

// ------------------------------------------------------------- helpers

/** Smooth normals while indexed, then non-indexed (for barycentric wire lines). */
function prep(geo, smooth = true) {
  let g = geo
  if (g.attributes.uv) g.deleteAttribute('uv')
  if (g.attributes.uv1) g.deleteAttribute('uv1')
  if (smooth) g.computeVertexNormals()
  if (g.index) g = g.toNonIndexed()
  if (!smooth) g.computeVertexNormals()
  return g
}

function merge(parts) {
  const geo = mergeGeometries(parts.map((p) => prep(p)))
  parts.forEach((p) => p.dispose())
  return geo
}

/** Normalise to the unit box centred at the origin and add barycentrics. */
function finish(geo) {
  geo.computeBoundingBox()
  const bb = geo.boundingBox
  const size = new THREE.Vector3()
  const center = new THREE.Vector3()
  bb.getSize(size)
  bb.getCenter(center)
  geo.translate(-center.x, -center.y, -center.z)
  geo.scale(1 / Math.max(1e-6, size.x), 1 / Math.max(1e-6, size.y), 1 / Math.max(1e-6, size.z))
  // Keep the normals from prep() (smooth for carved pieces, faceted for hulls);
  // scale() already transformed them with the normal matrix.
  if (!geo.attributes.normal) geo.computeVertexNormals()
  const g = geo.index ? geo.toNonIndexed() : geo
  const n = g.attributes.position.count
  const bary = new Float32Array(n * 3)
  for (let i = 0; i < n; i += 1) bary[i * 3 + (i % 3)] = 1
  g.setAttribute('bary', new THREE.BufferAttribute(bary, 3))
  return g
}

/** Points of an arc (centre, radius, a0 → a1). */
function arc2(cx, cy, r, a0, a1, n) {
  const out = []
  for (let i = 0; i <= n; i += 1) {
    const a = a0 + ((a1 - a0) * i) / n
    out.push(new THREE.Vector2(cx + r * Math.cos(a), cy + r * Math.sin(a)))
  }
  return out
}

// ------------------------------------------------------------- dressed stone

/**
 * Ashlar: convex hull of a chamfered block. Dressing → crisper chamfer, flat
 * faces; low dressing → pitched (bulging) rough-hewn faces and irregular arrises.
 */
function ashlar(rand, irregularity, dressing) {
  const pts = []
  const ch = 0.03 + 0.1 * dressing
  const rough = (1 - dressing) * (0.05 + irregularity * 0.12)
  for (const sx of [-1, 1])
    for (const sy of [-1, 1])
      for (const sz of [-1, 1]) {
        const j = () => 1 - rough * rand()
        pts.push(new THREE.Vector3(sx * (0.5 - ch) * j(), sy * 0.5 * j(), sz * 0.5 * j()))
        pts.push(new THREE.Vector3(sx * 0.5 * j(), sy * (0.5 - ch) * j(), sz * 0.5 * j()))
        pts.push(new THREE.Vector3(sx * 0.5 * j(), sy * 0.5 * j(), sz * (0.5 - ch) * j()))
      }
  // Pitched faces: bulge points pushed beyond the face plane (rock-faced ashlar).
  const bulges = Math.round(2 + (1 - dressing) * 10)
  for (let i = 0; i < bulges; i += 1) {
    const axis = Math.floor(rand() * 3)
    const sign = rand() < 0.5 ? -1 : 1
    const v = [(rand() - 0.5) * 0.7, (rand() - 0.5) * 0.7, (rand() - 0.5) * 0.7]
    v[axis] = sign * (0.5 + rough * 0.8 * rand())
    pts.push(new THREE.Vector3(...v))
  }
  return finish(prep(new ConvexGeometry(pts), false))
}

/** Rubble: chipped irregular hull (gravel, fallen stone). */
function rubble(rand, irregularity) {
  const pts = []
  for (let i = 0; i < 18; i += 1) {
    const u = rand() * TAU
    const v = Math.acos(2 * rand() - 1)
    const r = 0.5 * (1 - irregularity * 0.35 * rand())
    pts.push(new THREE.Vector3(r * Math.sin(v) * Math.cos(u), r * Math.cos(v) * 0.7, r * Math.sin(v) * Math.sin(u)))
  }
  return finish(prep(new ConvexGeometry(pts), false))
}

/** Column drum: lathe of a chamfered rectangle, slightly irregular. */
function drum(rand, irregularity) {
  const ch = 0.05
  const prof = [new THREE.Vector2(0, -0.5), new THREE.Vector2(0.5 - ch, -0.5), new THREE.Vector2(0.5, -0.5 + ch), new THREE.Vector2(0.5, 0.5 - ch), new THREE.Vector2(0.5 - ch, 0.5), new THREE.Vector2(0, 0.5)]
  const g = new THREE.LatheGeometry(prof, 20)
  const pos = g.attributes.position
  const wob = irregularity * 0.03
  const ph = rand() * TAU
  for (let i = 0; i < pos.count; i += 1) {
    const x = pos.getX(i)
    const z = pos.getZ(i)
    const a = Math.atan2(z, x)
    const k = 1 + wob * Math.sin(3 * a + ph) * (Math.hypot(x, z) > 0.3 ? 1 : 0)
    pos.setXYZ(i, x * k, pos.getY(i), z * k)
  }
  return finish(prep(g))
}

/**
 * Moulded section (REF-008 mullion / rib sections): a square whose four
 * corners are cut by concave quarter circles (hollow chamfers), with a
 * convex roll on the two working faces. Variant 1 uses straight chamfers
 * and a pointed keel.
 */
function mouldedShape(variant) {
  const rho = variant === 0 ? 0.2 : 0.16
  // Working faces (±x): a convex roll (variant 0) or a pointed keel (variant 1).
  const roll = (sx) => arc2(sx * 0.5, 0, 0.12, sx > 0 ? -Math.PI / 2 : Math.PI / 2, sx > 0 ? Math.PI / 2 : (3 * Math.PI) / 2, 8)
  const keel = (sx) => [new THREE.Vector2(sx * 0.5, -0.1 * sx), new THREE.Vector2(sx * 0.64, 0), new THREE.Vector2(sx * 0.5, 0.1 * sx)]
  const face = (sx) => (variant === 0 ? roll(sx) : keel(sx))
  // Walk CCW: right face → (1,1) → (−1,1) → left face → (−1,−1) → (1,−1).
  const pts = [
    ...face(1),
    ...cornerPts(1, 1, rho, variant),
    ...cornerPts(-1, 1, rho, variant),
    ...face(-1),
    ...cornerPts(-1, -1, rho, variant),
    ...cornerPts(1, -1, rho, variant),
  ]
  return new THREE.Shape(pts)
}

/** Corner cut points walking CCW around the square. */
function cornerPts(sx, sy, rho, variant) {
  // Entering the corner along the edge, leaving along the next edge (CCW).
  // CCW order of corners: (1,1) → (−1,1) → (−1,−1) → (1,−1).
  const enter = sx * sy > 0 ? new THREE.Vector2(sx * 0.5, sy * (0.5 - rho)) : new THREE.Vector2(sx * (0.5 - rho), sy * 0.5)
  const leave = sx * sy > 0 ? new THREE.Vector2(sx * (0.5 - rho), sy * 0.5) : new THREE.Vector2(sx * 0.5, sy * (0.5 - rho))
  if (variant !== 0) return [enter, leave]
  // Hollow chamfer: concave arc centred on the corner point.
  const a0 = Math.atan2(enter.y - sy * 0.5, enter.x - sx * 0.5)
  let a1 = Math.atan2(leave.y - sy * 0.5, leave.x - sx * 0.5)
  let sweep = a1 - a0
  while (sweep > Math.PI) sweep -= TAU
  while (sweep < -Math.PI) sweep += TAU
  a1 = a0 + sweep
  return arc2(sx * 0.5, sy * 0.5, rho, a0, a1, 6)
}

function moulded(variant, axis, irregularity = 0, rand = Math.random) {
  const g = new THREE.ExtrudeGeometry(mouldedShape(variant), { depth: 1, bevelEnabled: false, curveSegments: 6, steps: 4 })
  g.translate(0, 0, -0.5)
  // Weathered / chipped arrises: pull profile points inward by a seeded amount
  // (more at the ends of the bar), scaled by irregularity.
  if (irregularity > 0) {
    const pos = g.attributes.position
    const memo = new Map()
    for (let i = 0; i < pos.count; i += 1) {
      const x = pos.getX(i)
      const y = pos.getY(i)
      const z = pos.getZ(i)
      const key = `${x.toFixed(4)},${y.toFixed(4)},${z.toFixed(4)}`
      let k = memo.get(key)
      if (k === undefined) {
        const end = Math.pow(Math.abs(z) * 2, 3)
        k = 1 - irregularity * (0.05 + 0.18 * end) * rand()
        memo.set(key, k)
      }
      pos.setXYZ(i, x * k, y * k, z)
    }
  }
  if (axis === 'y') g.rotateX(-Math.PI / 2) // profile in X–Z, extruded along Y (rib voussoir)
  else g.rotateY(Math.PI / 2) // profile in Y–Z, extruded along X (tracery bar)
  return finish(prep(g, false))
}

// ------------------------------------------------------------- bosses

/**
 * Ceiling boss: polar surface over an n-foil outline (lobe circles on a
 * regular polygon, §4). Height = domed profile + central knob, with grooves
 * along the cusp lines. Face toward +Y.
 */
function bossGeometry(L) {
  const lam = minLobeRatio(L) * 1.015 + (0.5 - minLobeRatio(L)) * 0.35
  const phi0 = Math.PI / 2
  const nA = L * 24
  const nR = 14
  const maxR = foilRadiusAt(phi0, L, lam, phi0)
  const pos = []
  const idx = []
  for (let j = 0; j <= nR; j += 1) {
    const t = j / nR
    for (let i = 0; i < nA; i += 1) {
      const th = (TAU * i) / nA
      const R = foilRadiusAt(th, L, lam, phi0) / maxR
      // Angular distance to the nearest cusp direction (between lobes).
      const rel = (((th - phi0) % (TAU / L)) + TAU / L) % (TAU / L)
      const toCusp = Math.abs(rel - Math.PI / L)
      const groove = 1 - 0.45 * Math.exp(-((Math.PI / L - toCusp) ** 2) / 0.01) * Math.min(1, Math.max(0, (t - 0.25) / 0.6))
      const dome = Math.pow(Math.max(0, 1 - t * t), 0.7)
      const knob = 0.35 * Math.exp(-((t / 0.2) ** 2))
      const y = 0.5 * dome * groove + knob
      pos.push(Math.cos(th) * R * t * 0.5, y, Math.sin(th) * R * t * 0.5)
    }
  }
  for (let j = 0; j < nR; j += 1)
    for (let i = 0; i < nA; i += 1) {
      const a = j * nA + i
      const b = j * nA + ((i + 1) % nA)
      const c = a + nA
      const d = b + nA
      idx.push(a, b, c, b, d, c) // faces +Y (outward)
    }
  // Flat back: fan to a centre point at y = 0.
  const center = pos.length / 3
  pos.push(0, 0, 0)
  const rim = nR * nA
  for (let i = 0; i < nA; i += 1) idx.push(center, rim + i, rim + ((i + 1) % nA))
  const g = new THREE.BufferGeometry()
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3))
  g.setIndex(idx)
  return g
}

// ------------------------------------------------------------- keystone

function keystone() {
  const s = new THREE.Shape()
  s.moveTo(-0.5, 0.5)
  s.lineTo(0.5, 0.5)
  s.lineTo(0.36, -0.28)
  s.lineTo(0.2, -0.28)
  // Pendant drop: two arcs meeting in a point (a small inverted pointed arch).
  s.absarc(0.2 + 0.32, -0.28, 0.32, Math.PI, Math.PI + 1.08, false)
  s.absarc(-0.2 - 0.32, -0.28, 0.32, -1.08, 0, false)
  s.lineTo(-0.36, -0.28)
  s.lineTo(-0.5, 0.5)
  const body = new THREE.ExtrudeGeometry(s, { depth: 0.8, bevelEnabled: true, bevelThickness: 0.04, bevelSize: 0.03, bevelSegments: 1, curveSegments: 10 })
  body.translate(0, 0, -0.4)
  const parts = [body]
  for (const sz of [1, -1]) {
    const rose = bossGeometry(4)
    rose.scale(0.42, 0.22, 0.42)
    rose.rotateX(sz > 0 ? Math.PI / 2 : -Math.PI / 2)
    rose.translate(0, 0.1, sz * 0.44)
    parts.push(rose)
  }
  return finish(merge(parts))
}

// ------------------------------------------------------------- pinnacle, crocket, finial

function crocketGeometry(scale = 1) {
  // Hook: a logarithmic spiral swept as a tapering tube, ending in a bud.
  const pts = []
  for (let i = 0; i <= 14; i += 1) {
    const th = (i / 14) * Math.PI * 1.5
    const r = 0.5 * Math.exp(-0.32 * th)
    pts.push(new THREE.Vector3((0.5 - r * Math.cos(th)) * scale, r * Math.sin(th) * scale + i * 0.02 * scale, 0))
  }
  const tube = new THREE.TubeGeometry(new THREE.CatmullRomCurve3(pts), 18, 0.16 * scale, 7, false)
  const bud = new THREE.SphereGeometry(0.22 * scale, 8, 6)
  const end = pts[pts.length - 1]
  bud.translate(end.x, end.y, end.z)
  return [tube, bud]
}

function finialParts(y0, s) {
  const parts = []
  const bud = new THREE.LatheGeometry(
    [new THREE.Vector2(0, 0), new THREE.Vector2(0.09, 0.05), new THREE.Vector2(0.12, 0.2), new THREE.Vector2(0.06, 0.38), new THREE.Vector2(0, 0.46)].map((v) => v.multiplyScalar(s)),
    10,
  )
  bud.translate(0, y0, 0)
  parts.push(bud)
  for (let k = 0; k < 4; k += 1) {
    const leaf = new THREE.SphereGeometry(0.11 * s, 8, 6)
    leaf.scale(1.6, 0.55, 0.8)
    leaf.translate(0.16 * s, y0 + 0.12 * s, 0)
    leaf.rotateY((TAU * k) / 4)
    parts.push(leaf)
  }
  return parts
}

function pinnacle() {
  const parts = []
  const shaft = new THREE.BoxGeometry(0.6, 1.4, 0.6)
  shaft.translate(0, 0.7, 0)
  parts.push(shaft)
  // Gablets on the four faces.
  for (let k = 0; k < 4; k += 1) {
    const tri = new THREE.Shape([new THREE.Vector2(-0.3, 0), new THREE.Vector2(0.3, 0), new THREE.Vector2(0, 0.42)])
    const g = new THREE.ExtrudeGeometry(tri, { depth: 0.1, bevelEnabled: false })
    g.translate(0, 1.4, 0.26)
    g.rotateY((TAU * k) / 4)
    parts.push(g)
  }
  const spire = new THREE.ConeGeometry(0.44, 2.3, 4)
  spire.rotateY(Math.PI / 4)
  spire.translate(0, 1.4 + 1.15, 0)
  parts.push(spire)
  // Crockets climbing the four spire edges.
  for (let e = 0; e < 4; e += 1)
    for (let i = 0; i < 4; i += 1) {
      const u = 0.12 + i * 0.21
      const [tube, bud] = crocketGeometry(0.24 * (1 - u * 0.6))
      for (const g of [tube, bud]) {
        g.translate(0.44 * (1 - u) * 0.71 * 1.414 - 0.02, 1.4 + 2.3 * u, 0)
        g.rotateY(Math.PI / 4 + (TAU * e) / 4)
        parts.push(g)
      }
    }
  parts.push(...finialParts(1.4 + 2.3 - 0.05, 1.2))
  return finish(merge(parts))
}

function crocket() {
  return finish(merge(crocketGeometry(1)))
}

function finial() {
  return finish(merge(finialParts(0, 2)))
}

// ------------------------------------------------------------- capital, base

function capital() {
  const parts = []
  // Astragal (half round) + bell (concave circular arc) as one lathe profile.
  const prof = [new THREE.Vector2(0, 0), new THREE.Vector2(0.34, 0)]
  prof.push(...arc2(0.36, 0.06, 0.06, -Math.PI / 2, Math.PI / 2, 6))
  // Concave bell: arc centred at (0.36 + R, 0.12) through (0.36, 0.12) and (0.5, 0.64).
  const R = (0.14 ** 2 + 0.52 ** 2) / (2 * 0.14) // solves (0.14 − R)² + 0.52² = R²
  const cx = 0.36 + R
  const aTop = Math.atan2(0.52, 0.5 - cx)
  prof.push(...arc2(cx, 0.12, R, Math.PI, aTop, 10))
  prof.push(new THREE.Vector2(0, 0.64))
  parts.push(new THREE.LatheGeometry(prof, 24))
  const abacus = new THREE.CylinderGeometry(0.62, 0.6, 0.16, 8)
  abacus.translate(0, 0.72, 0)
  parts.push(abacus)
  // Stiff-leaf knobs under the abacus (eight, rotational symmetry).
  for (let k = 0; k < 8; k += 1) {
    const knob = new THREE.SphereGeometry(0.1, 10, 8)
    knob.scale(1.1, 0.8, 0.9)
    knob.translate(0.5, 0.56, 0)
    knob.rotateY((TAU * k) / 8 + Math.PI / 8)
    parts.push(knob)
  }
  return finish(merge(parts))
}

function base() {
  const parts = []
  const plinth = new THREE.CylinderGeometry(0.58, 0.6, 0.32, 8)
  plinth.translate(0, 0.16, 0)
  parts.push(plinth)
  // Attic profile: lower torus, scotia (concave arc), upper torus.
  const prof = [new THREE.Vector2(0, 0.32), new THREE.Vector2(0.4, 0.32)]
  prof.push(...arc2(0.4, 0.42, 0.1, -Math.PI / 2, Math.PI / 2, 8))
  prof.push(...arc2(0.42, 0.57, 0.05, -Math.PI / 2, -Math.PI * 1.5, 6))
  prof.push(...arc2(0.36, 0.67, 0.05, -Math.PI / 2, Math.PI / 2, 6))
  prof.push(new THREE.Vector2(0.32, 0.8), new THREE.Vector2(0, 0.8))
  parts.push(new THREE.LatheGeometry(prof, 24))
  return finish(merge(parts))
}

// ------------------------------------------------------------- grotesque

/**
 * Grotesque / gargoyle (REF-018, REF-020): bilaterally symmetric body lofted
 * along a parametric spine (+X = projecting outward, +Y = up), open jaw,
 * eyes, swept horns, dorsal spines and gripping forelegs on a wall block.
 */
function grotesque(variant) {
  const parts = []
  const curl = [0.12, 0.2, 0.06][variant]
  const spineY = (u) => curl * Math.sin(Math.PI * u) + 0.18 * u * u
  const keys = [
    [0, 0.24],
    [0.18, 0.3],
    [0.42, 0.22],
    [0.56, 0.15],
    [0.7, 0.21],
    [0.86, 0.15],
    [1, 0.04],
  ]
  const rad = (u) => {
    for (let i = 1; i < keys.length; i += 1)
      if (u <= keys[i][0]) {
        const t = (u - keys[i - 1][0]) / (keys[i][0] - keys[i - 1][0])
        const s = (1 - Math.cos(Math.PI * t)) / 2
        return keys[i - 1][1] + (keys[i][1] - keys[i - 1][1]) * s
      }
    return keys[keys.length - 1][1]
  }
  const nU = 40
  const nV = 14
  const pos = []
  const idx = []
  for (let i = 0; i <= nU; i += 1) {
    const u = i / nU
    const y = spineY(u)
    const r = rad(u)
    for (let j = 0; j < nV; j += 1) {
      const v = (TAU * j) / nV
      const ridge = 1 + 0.28 * Math.pow(Math.max(0, Math.sin(v)), 6)
      pos.push(u, y + Math.sin(v) * r * ridge, Math.cos(v) * r * 0.85)
    }
  }
  for (let i = 0; i < nU; i += 1)
    for (let j = 0; j < nV; j += 1) {
      const a = i * nV + j
      const b = i * nV + ((j + 1) % nV)
      idx.push(a, a + nV, b, b, a + nV, b + nV) // outward normals
    }
  const body = new THREE.BufferGeometry()
  body.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3))
  body.setIndex(idx)
  parts.push(body)
  // Lower jaw (open, angled down).
  const jawPts = []
  for (let i = 0; i <= 8; i += 1) {
    const u = 0.72 + (0.24 * i) / 8
    jawPts.push(new THREE.Vector3(u, spineY(u) - 0.09 - (u - 0.72) * 0.45, 0))
  }
  parts.push(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(jawPts), 10, 0.045, 7, false))
  for (const sz of [-1, 1]) {
    const eye = new THREE.SphereGeometry(0.035, 8, 6)
    eye.translate(0.8, spineY(0.8) + 0.08, sz * 0.09)
    parts.push(eye)
    // Horns: swept tubes curling back and out (mirror pair).
    const horn = []
    for (let i = 0; i <= 10; i += 1) {
      const s = i / 10
      const a = s * Math.PI * (0.9 + 0.3 * variant)
      horn.push(new THREE.Vector3(0.74 - 0.22 * Math.sin(a * 0.8), spineY(0.74) + 0.12 + 0.16 * Math.sin(a), sz * (0.07 + 0.16 * s)))
    }
    parts.push(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(horn), 12, 0.028, 6, false))
    // Forelegs gripping the block.
    const leg = [new THREE.Vector3(0.2, spineY(0.2) - 0.12, sz * 0.13), new THREE.Vector3(0.3, -0.12, sz * 0.18), new THREE.Vector3(0.24, -0.3, sz * 0.17)]
    parts.push(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(leg), 8, 0.045, 6, false))
  }
  // Dorsal spines along the back.
  const spines = [4, 6, 3][variant]
  for (let k = 0; k < spines; k += 1) {
    const u = 0.15 + (0.45 * k) / Math.max(1, spines - 1)
    const c = new THREE.ConeGeometry(0.035, 0.12, 5)
    c.rotateZ(-0.5)
    c.translate(u, spineY(u) + rad(u) * 1.25, 0)
    parts.push(c)
  }
  const block = new THREE.BoxGeometry(0.3, 0.55, 0.5)
  block.translate(-0.08, -0.1, 0)
  parts.push(block)
  return finish(merge(parts))
}

// ------------------------------------------------------------- registry

/**
 * All prototypes in registry order (see lithic/protos.js).
 * irregularity / dressing only affect the dressed-stone families.
 */
export function createStonePrototypes(irregularity = 0.3, dressing = 0.7, seed = 11) {
  const rand = mulberry32(seed)
  const out = new Array(PROTOTYPE_COUNT)
  const fill = (name, make) => {
    const p = PROTO[name]
    for (let k = 0; k < p.count; k += 1) out[p.start + k] = make(k)
  }
  fill('ashlar', () => ashlar(rand, irregularity, dressing))
  fill('rubble', () => rubble(rand, Math.max(0.3, irregularity)))
  fill('drum', () => drum(rand, irregularity))
  fill('ribVoussoir', (k) => moulded(k, 'y', irregularity, rand))
  fill('bar', (k) => moulded(k, 'x', irregularity, rand))
  fill('keystone', () => keystone())
  fill('boss', (k) => finish(prep(bossGeometry(BOSS_LOBES[k]))))
  fill('pinnacle', () => pinnacle())
  fill('capital', () => capital())
  fill('base', () => base())
  fill('grotesque', (k) => grotesque(k))
  fill('crocket', () => crocket())
  fill('finial', () => finial())
  return out
}
